INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018936', 'AN1817', '松風佳乃子', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b249082-A8sX6F5w7FEe.jpg', NULL, NULL, '髙橋ミナミ', NULL, 249082, 'SUPPORTING', 43) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018937', 'AN1818', '村尾潤平', '幼い頃からバレエに親しんでいた14歳の少年。スタントマンだった父親が亡くなったことをきっかけに、その夢を断念した。 一家で唯一の男子であるため、叔父の助言に従い、家族の支えとなるべく「男らしく」あるべきだと考え、バレエを辞め、代わりに叔父の指導のもとでジークンドーを練習するようになった。 ミヤコとの出会いをきっかけに、ジュンペイのバレエへの情熱が再燃し、ルー・ディーを見たことをきっかけに、自分自身と「男らしさ」の意味を再発見し始める。', 14, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b154110-kFYVapqqvzhA.jpg', NULL, NULL, '山下大輝', NULL, 154110, 'MAIN', 137) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018938', 'AN1818', '五代都', 'ルオのいとこ。14歳の少女で、千鶴の娘。都は幼い頃から母親にバレエを習ってきた。実力はあるものの、その性格から、母親は彼女を主要な役柄には不向きだと見なしている。 ミヤコはジュンペイの才能を見出し、彼にバレエの素質があることに気づく。それがきっかけで、ジュンペイはダンスへの情熱を再燃させる。親切で礼儀正しいミヤコは、どちらも大切に思っているジュンペイとルオに対して複雑な思いを抱いている。特にルオのことが心配で、', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b262763-lqgmdSmc8e0K.png', NULL, NULL, '本渡楓', NULL, 262763, 'MAIN', 59) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018939', 'AN1818', '森流鶯', '内気な14歳の少年で、ミヤコのいとこである。アメリカのアイドルの息子だが、母親が夫以外の男性との間に彼をもうけたことがスキャンダルとして明るみに出た後、母親に見捨てられた。 厳格でバレエに没頭する祖母に育てられたルオは、外界との接触がほとんどない、肉体的・精神的な虐待が横行する環境下で育ち、バレエだけを学んできた。その結果、ルオの対人スキルは未熟だが、そのダンスの腕前は比類のないものだ。その並外れた', 14, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b262764-cvRRZbsliCA0.png', NULL, NULL, '内山昂輝', NULL, 262764, 'MAIN', 55) ON CONFLICT DO NOTHING;
