INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018945', 'AN1818', '姫乃小路寿', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b275491-DLc8MNuysGPz.jpg', NULL, NULL, '井之上潤', NULL, 275491, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018946', 'AN1818', '生川夏姫', '小学6年生の少女で、綾子の娘。夏樹は同年代の子供たちとは比べ物にならないほど才能に恵まれたダンサーだが、普段は真面目すぎて表情が乏しい。向上心旺盛で完璧主義者の夏樹は、最高を目指し、バレエに並々ならぬ努力を注いでいる。 夏樹は、表現力豊かな踊りが自身の考えと合致していることから、ダンサーとしての純平に惹かれている。二人はバレエに対する考え方に多くの共通点があり、完璧な息の合った踊りを披露してきた。そこには、', 12, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b275492-bzo5N88vCiHG.png', NULL, NULL, '福圓美里', NULL, 275492, 'SUPPORTING', 134) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018947', 'AN1818', '安田海咲', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b275493-K5LdtuFKOlei.jpg', NULL, NULL, '天崎滉平', NULL, 275493, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018948', 'AN1819', '千代田桃', '千代田桃は、清木桜ヶ丘の町を守っている魔法少女だ。魔法少女として、彼女は筋トレマニアであり、その身体能力は、町のライバルであるサキュバス・ユウコを圧倒的に上回っている。 彼女の魔法少女としての経歴は謎に包まれており、かつて世界を救ったという噂もある。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b141457-zbvICmxe7kgM.png', '3月25日', NULL, '鬼頭明里', NULL, 141457, 'MAIN', 668) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018949', 'AN1819', '吉田優子', '吉田優子は、高校1年生の時に突然力が目覚めた悪魔で、家族の呪いを解くために、町に住む魔法少女を倒そうとしている。 しかし、他人の夢に忍び込む能力は持っているものの、体力や持久力はライバルである魔法少女・千代田桃に比べてはるかに劣っている。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b141461-5ZkxFDzP408S.png', '9月28日', NULL, '小原好美', NULL, 141461, 'MAIN', 1335) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018950', 'AN1819', '吉田良子', '吉田良子はユウコの妹です。良子の夢は、姉が恐ろしい妖怪になれるよう支えることです。', 9, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b141462-8MiGTh3GvC8p.jpg', '1月7日', NULL, '大和田仁美', NULL, 141462, 'SUPPORTING', 54) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018951', 'AN1819', '吉田清子', '吉田清子は、ユウコとリョウコの母親です。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b141459-K9skF3ouZ615.jpg', NULL, NULL, '大原さやか', NULL, 141459, 'SUPPORTING', 50) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018952', 'AN1819', '陽夏木ミカン', '陽夏木ミカンは、モモを応援するためにこの町にやってきた魔法少女だ。彼女は、興奮しすぎたり不安になったりすると、身近な人たちに不幸をもたらしてしまうという呪いにかかっている。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b141458-NGjjJhP1xLRx.png', '11月3日', NULL, '高柳知葉', NULL, 141458, 'SUPPORTING', 247) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018953', 'AN1819', '浅瀬先生', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b269926-icxr1focW14W.png', NULL, NULL, '佐藤聡美', NULL, 269926, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018954', 'AN1819', 'リリス', 'リリスはユウコの悪魔の祖先である。ある夜、彼女はユウコの夢の中に現れ、悪魔の力を授けるとともに、ある魔法少女を倒すよう命じた。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b141460-soOz8LIuhD4w.png', NULL, NULL, '髙橋ミナミ', NULL, 141460, 'SUPPORTING', 141) ON CONFLICT DO NOTHING;
