INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018956', 'AN1819', 'リコ', 'リコは、「アスラ・カフェ」でウェイトレス兼シェフを務める狐の妖怪です。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b265650-TcXDj78LvhUL.png', NULL, NULL, '伊藤彩沙', NULL, 265650, 'SUPPORTING', 98) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018957', 'AN1819', '白澤店長', 'シロサワはタピールの妖怪で、「アスラカフェ」のオーナーです。彼は、タマサクラ商店街のマスコットキャラクター「タマサクラちゃん」の生みの親でもあります。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b265651-dB56sXOeeXMP.png', NULL, NULL, '松山鷹志', NULL, 265651, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018958', 'AN1819', '小倉しおん', '小倉しおんは、ユウコの友人であり同級生です。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b141464-6WBnBnhxWstk.png', '12月14日', NULL, '諏訪彩花', NULL, 141464, 'SUPPORTING', 31) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018959', 'AN1819', '佐田杏里', '佐田杏里はユウコの友人であり、同級生です。', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b141463-SBGcYr7wTt8D.jpg', '5月1日', NULL, '千本木彩花', NULL, 141463, 'SUPPORTING', 17) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018960', 'AN1820', '天鷲葵', '天鷲葵は、世界最大級の企業の一つである天鷲グループの令嬢であり、ゴルフ界の純血種である。 名門・雷神女子学園ゴルフ部のエースである葵は、ゴルフを楽しみながら、甘く無邪気な笑顔を浮かべて対戦相手を打ち負かすことから、「無邪気な暴君」として知られるようになった。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b253819-ui4XCjXVnag3.png', NULL, NULL, '瀬戸麻沙美', NULL, 253819, 'MAIN', 135) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018961', 'AN1820', 'イヴ', 'イヴは『BIRDIE WING -Golf Girls'' Story-』シリーズの主人公です。彼女はゴルフの賭けで生計を立てていたサバイバーです。苦難に満ちた過去が、荒々しくも力強いプレースタイルを生み出しました。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b253820-yVhieWvjxZNO.png', NULL, NULL, '鬼頭明里', NULL, 253820, 'MAIN', 250) ON CONFLICT DO NOTHING;
