INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018979', 'AN1820', '亜室麗矢', '亜室麗矢は、雷神女子学園のゴルフ部のヘッドコーチである。かつてプロゴルファーとして活躍したが、そのキャリアは短命に終わった。現在はゴルフ部を率いるとともに、プロとしての道を歩み始めた葵のメンターも務めている。また、イヴをチームに迎え入れ、ある程度まで指導も行っている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258745-x10WDg0SecTw.png', NULL, NULL, '古谷徹', NULL, 258745, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
