INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018983', 'AN1820', 'レオ・ミラフォーデン', 'レオ・ミラフォーデンはアンダーグラウンドのゴルファーであり、イヴの幼少期の大部分において彼女のゴルフコーチを務めていた。レオのおかげで、イヴは「バレット」と呼ばれる高エネルギーのゴルフスイングの使い方を習得することができた。やがて、レオはイヴを独りきりにして去っていった。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258746-4wo4jMeOfsOL.png', NULL, NULL, '池田秀一', NULL, 258746, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
