INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018994', 'AN1820', 'アンリ', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b307568-a7doyOTSofeV.jpg', NULL, NULL, '小見川千明', NULL, 307568, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018995', 'AN1821', '柴崎愛蔵', '柴崎愛蔵（芸名：アイゾ）は、『告白実行委員会』に登場するキャラクターであり、『アイドルシリーズ』の主要キャラクターの一人、そしてLIP×LIPのメンバーである。彼は1年4組に所属し、サブキャストたちが高校2年生の時に桜ヶ丘高校の生徒として描かれている。 彼は柴崎健の弟である。アイゾは社交的な性格で、おしゃべり好きであり、出会う人すべてに親しみやすい。アイドルとしての彼のイメージは、非常に愛想が良く、親しみやすいと広く知られている。', 14, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b182644-laBNdKgG5w1O.jpg', '2月22日', 'A', '島﨑信長', NULL, 182644, 'MAIN', 131) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018996', 'AN1821', '染谷勇次郎', '染谷勇次郎（芸名：ユウジロウ）は、『告白実行委員会』ソングシリーズの登場人物であり、『アイドルシリーズ』の主要キャラクターの一人、そしてLIP×LIPのメンバーである。サブキャストが高校2年生だった当時、桜ヶ丘高校1年4組に在籍していた。  ユジロは同年代の男子としては小柄で、短めのダークブルーの髪は前髪が斜めにアシンメトリーにカットされ、数本の髪が立ち上がっている。瞳も髪と同じ青色だ。LIP×LIPの一員になる前は、', 14, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b182643-nB9VO9hrQlfI.jpg', '2月22日', 'B', '内山昂輝', NULL, 182643, 'MAIN', 144) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018997', 'AN1821', '涼海ひより', '彼女は、桜ヶ丘高校1年1組の2年目に在籍している高校1年生です。 地方の小さな町出身のため、ひよりさんは都会の生活にまだあまり慣れておらず、東京のさまざまなものに強い興味を持っています。 これまでのメディアでの情報から判断すると、彼女は楽観的で、やや純真な性格の少女のようで、とても道に迷いやすい。また、特に女子の間で人気のある歌手であるLIP×LIPやASCANAを知らないことから、文化的な知識があまりないようにも見える。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b182641-l8mc9cS54va4.jpg', '3月31日', 'O', '水瀬いのり', NULL, 182641, 'MAIN', 172) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018998', 'AN1821', '服部樹里', '服部樹里は、桜ヶ丘高校1年4組の生徒であり、涼海ひよりの最初の女友達の一人であり、同級生でもある。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b245853-tROaFmpsYe7x.png', '11月5日', NULL, '佐倉綾音', NULL, 245853, 'SUPPORTING', 58) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018999', 'AN1821', '瀬戸口雛', 'ユウの妹。明るく、可愛らしく、元気いっぱいの女の子だ。悲しい時や嬉しい時に感情を大げさに表現するため、その表現力はナツキに引けを取らない。 明るい性格とは裏腹に、彼女にも不安を抱えている。好きな人にうまくアプローチできないと感じており、小雪との関係において、自分の気持ちを伝える一歩手前でいつも止まってしまう。そのことが彼女を限りなく苛立たせている。手に入れるために多大な努力を重ねているにもかかわらず、', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n133897-uBqvnULJLFUK.png', '8月8日', 'A', '麻倉もも', 149, 133897, 'SUPPORTING', 147) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019000', 'AN1821', 'リオ', 'リオは「フル・スロットル4」のメンバーだ。彼はグループのリードボーカルの一人であり、高校2年生である。クールでタフな男だ。一歩引いて場の空気を読むタイプで、グループの「ブレーキ」的な役割を担っている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b191406-IWRt7xXpJu2t.jpg', '10月1日', 'A', '内田雄馬', NULL, 191406, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019001', 'AN1821', '中村千鶴', '中村千鶴は、桜ヶ丘高校1年4組の生徒であり、涼海ひよりの最初の女友達の一人であり、同級生でもある。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b245852-e9NUO8sZahCA.png', '5月13日', NULL, '早見沙織', NULL, 245852, 'SUPPORTING', 37) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019002', 'AN1821', 'ダイ', 'ダイは「フル・スロットル4」のメンバーである。彼はグループの主力パフォーマーの一人であり、高校3年生だ。ダイは、自信に満ち溢れた派手なナルシストとして知られている。メグは、小学校の頃からダイを知っているという特筆すべき点があり、彼の両親に関する事情も把握している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b191403-sP7UC4FBm0sq.jpg', '7月4日', 'B', '増田俊樹', NULL, 191403, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019003', 'AN1821', '田村レイ', '彼女は、LIP×LIPやFull Throttle4が所属する芸能事務所「モビウス」の社長である。大手芸能事務所での勤務経験があり、才能あるプロデューサーとして知られている。 レイはオーディションでアイゾとユウジロウを選抜した人物であり、性格が対立する二人であるにもかかわらず、彼らをペアにするという先見の明を持っていた。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b189363-i37W48ssebZ1.png', NULL, NULL, '沢城みゆき', NULL, 189363, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019004', 'AN1821', '高見沢アリサ', 'アリサは桜ヶ丘高校の1年生の一人で、榎本虎太朗の友人であり、柴崎健の主な恋愛対象である。  中学時代、アリサはいじめの事件が起こるまではやや従順な性格で、たとえ気が進まなくてもクラスの他の生徒たちの言うことや行動に合わせるようなところがあった。 普段は思いやりのある性格であるだけに、これは彼女にとって大きな弱点だったが、適切な後押しがあれば自分の感情を素直に認めるタイプだ。彼女はとても勇敢で、', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n134009-6vU2Jqm60Y9E.jpg', '2月3日', 'B', '東山奈央', 150, 134009, 'SUPPORTING', 44) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019005', 'AN1821', '内田茉優', '芸能事務所「モビウス」に所属するマネージャー。オーディションに合格したユウジロウとアイゾウの担当を務めている。彼女はアイゾウとユウジロウの本当の姿を把握している。二人の喧嘩にはしばしば頭を抱えるが、その才能と実力も認めている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b189366-de23gA1rJuh9.png', NULL, NULL, '茅野愛衣', NULL, 189366, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019006', 'AN1821', 'メグ', 'メグは「Full Throttle4」のメンバー。グループの主力パフォーマーの一人であり、高校3年生だ。  いたずら好きで自由奔放な性格の持ち主で、グループ内ではおしゃべりなモデレーターを務めている。裕福な家庭に育ったが、亡くなった愛犬レイラを除けば、家族とは特に親しい関係にはないようだ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b191405-nsusNE7JIWBm.jpg', '6月12日', 'O', '柿原徹也', NULL, 191405, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019007', 'AN1821', '明智咲', '明智咲は桜ヶ丘高校の国語教師を務めている。その冷静な頭脳と淡々とした人柄から、ほとんどの生徒から尊敬される教師と見なされている。彼は、生徒たちが行き詰まった際に、さまざまな日本文学のテキストから引用した公案を彼らの状況に当てはめてアドバイスをする習慣がある。 その気さくな物腰のおかげで、生徒たちとも気軽に接することができる。10代の頃の彼の性格はユウに似ていたが、今でもやはり外向的であり……', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n133670-bpJuBH3hsBZV.jpg', '5月29日', 'O', '緑川光', 183, 133670, 'SUPPORTING', 93) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019008', 'AN1821', '山本幸大', '桜ヶ丘高校1年1組の生徒であり、榎本虎太朗、柴崎健とともに「バカトリオ」を結成している仲間の一人。バカトリオの中で、コダイは断然最も冷静なメンバーである。 些細な不都合で動揺するようなタイプではないが、口調の変化や皮肉といった微妙な方法で、怒りや不快感を表すこともある。それ以外は静かで目立たず、傍らから皆の様子を見守っている。穏やかな性格の持ち主だ。さらに、彼は注意深く……', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b134008-e37j3dl031SS.png', '11月7日', 'A', '松岡禎丞', 172, 134008, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019009', 'AN1821', '白波渚', '陸上部の仲間。幼い頃からひよりを知っており、彼女を大切でかけがえのない存在だと考えている。一方、なぎさは、二人とも都会に出たら彼女になってほしいと頼むことから、ひよりに恋をしているようだ。 日和は高校に入るまで、彼が自分に抱いている恋心には気づいていなかったようだ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b273494-NNbVaCGehDwN.jpg', '6月30日', NULL, '榎木淳弥', NULL, 273494, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019010', 'AN1821', '成海聖奈', 'セナは、コンセプト上、女の子たちが憧れるような存在であり、男の子たちがデートしたいと思うタイプの女の子です。彼女は前向きで親しみやすく、強い自尊心を持っており、自分らしく生きることを大切にしています。家族のこととなると、その愛情を隠すことなく表に出します。 その人柄は、アリサや妹といった他のキャストメンバーにも良い影響を与えています。恋愛に関しては、セナは最初は恥ずかしがり屋ですが、一度交際が始まると、積極的と表現するのが最もふさわしいでしょう。相手に振り回されるよりは、', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n133898-c1AZtmw5Fh1X.png', '10月16日', 'B', '雨宮天', 160, 133898, 'SUPPORTING', 77) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019011', 'AN1821', 'ユイ', 'ユイは「フルスロットル4」のメンバーです。彼はグループのリードボーカルの一人であり、高校2年生です。明るくのんきな性格で、つい熱中しすぎてしまうこともよくあります。しかし、その裏には、クールな一面も持っています。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b191402-jcvRwFWrah1A.jpg', '3月4日', 'AB', '斉藤壮馬', NULL, 191402, 'SUPPORTING', 18) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019012', 'AN1821', '成海萌奈', '成海萌奈（ステージネームはmona）は、成海聖奈の妹であり、『告白実行委員会』に登場するキャラクターである。アイドルシリーズでは主要キャラクターとして活躍しているが、ラブシリーズでは脇役としてデビューした。職業はソロアイドルで、美鈴高校の生徒である。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155891-xPwyCMRt0Pux.png', '4月24日', 'AB', '夏川椎菜', 160, 155891, 'SUPPORTING', 99) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019013', 'AN1821', 'イヴ', 'IV (pronounced as "Eve"/イヴ, Ivu), is the manager and DJ of the music and dance idol unit Full Throttle4, and a third year high school student.  Even though he''s the behind-the-scenes leader who formed and leads the group, IV prefers to work offstage to help out the other four members. He''s rarely seen other than when he''s performing as DJ in live shows.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b191404-ak5hg4Z29oGA.jpg', '12月24日', 'A', '福山潤', NULL, 191404, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019014', 'AN1821', '柴崎健', 'ケンの最大の関心事は女性であり、彼はそれを隠そうとはしない。女子の同級生たちとよくイチャイチャしている姿が見られ、彼女たちの話をすることが好きで、さまざまな女の子と頻繁にデートに出かける。女性に対して気楽な態度をとっているとはいえ、ケンは男たちよりも女の子に対して親切で、積極的にアプローチするよりは、遠くから彼女たちを見守っている。 友人たちとは、いつも陽気で冗談ばかり言い、しばしば彼らをからかってイライラさせたりもする。その一見のんきな態度の裏には、実は真面目な一面が隠されているのだが、彼は', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n134007-RIM5TqQTPXwS.jpg', '4月1日', 'O', '江口拓也', 167, 134007, 'SUPPORTING', 27) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019015', 'AN1821', '榎本虎太朗', '榎本夏樹の弟。姉と同じように、小太郎も感情表現が豊かな人物だ。怒りっぽく、すぐにイライラしてしまう。', 16, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n133900-wMfpGA5eKSme.png', '11月29日', 'B', '花江夏樹', 160, 133900, 'SUPPORTING', 75) ON CONFLICT DO NOTHING;
