INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019051', 'AN1823', 'くノ一ツバキ', 'ツバキは「ドッグ・スクワッド」のリーダーであり、茜一族のトップの生徒だ。彼女は忍術全般に長けており、非常に真面目な性格のため、先生たちからも大きな期待を寄せられている。しかし、まだ面識のない「男性」となると、彼女は動揺してしまう。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b164151-VQhqj4AHlcU5.png', '4月1日', NULL, '夏吉ゆうこ', 155, 164151, 'MAIN', 254) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019052', 'AN1823', 'サザンカ', 'サザンカはドッグ・スクワッドのメンバーです。おっちょこちょいでいたずら好きな性格のせいで、周囲から誤解されやすく、先生たちからは問題児扱いされています。 その一方で、彼女は「ドッグ・スクワッド」のリーダーである<a href="https://anilist.co/character/164151/Tsubaki-Kunoichi">ツバキ</a>を慕っており、彼女を「ネエ様」と呼んでいる。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b260986-62tYMt2dOSP4.png', '11月7日', NULL, '根本京里', 133, 260986, 'MAIN', 120) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019053', 'AN1823', 'アサガオ', 'アサガオは「ドッグ・スクワッド」のメンバーです。彼女とクラスメイトの<a href="https://anilist.co/character/260986/サザンカ">サザンカ</a>は、見た目も性格も正反対の、対照的なコンビです。 彼女は大の食いしん坊で、1日3食よりも4～5食食べるほうが好きで、「ご飯抜き」という罰を他のどんな罰よりも嫌っている。くノ一ではあるが、忍術は得意ではない。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b260985-hKO9OHm8s4sK.png', '7月25日', NULL, '鈴代紗弓', 170, 260985, 'MAIN', 46) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019054', 'AN1823', 'リンドウ', 'リンドウは、葵一族からの転校生で、後にドッグ・スクワッドの4人目のメンバーとして加入する。彼女は内気な性格で、普段は狐の仮面をかぶって顔を隠している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b264490-o0IxtJbrAb0z.png', NULL, NULL, '小原好美', 147, 264490, 'MAIN', 95) ON CONFLICT DO NOTHING;
