INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019092', 'AN1824', '蒙武', '呂不韋の「四柱」の一人。孟天と孟義の父。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b70195-EG7Jhy0sKpFH.png', NULL, NULL, '楠大典', NULL, 70195, 'SUPPORTING', 100) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019093', 'AN1824', '媧燐', '媧燐は、現在の首相であり、楚国の武術界を率いる人物である。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b138865-ztJdRCgnsH79.jpg', NULL, NULL, '田中敦子', NULL, 138865, 'SUPPORTING', 31) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019094', 'AN1824', '吴凤明', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b159239-Sm41S3IlWFG1.jpg', NULL, NULL, '浪川大輔', NULL, 159239, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019095', 'AN1824', '凱孟', 'ガイ・モは、気さくで気取らない将軍であり、決闘する価値のある相手を見つけた時だけ戦場に出る。彼は非常に自慢屋で、自分の実力について嘘をつくことさえある。また、かなり鈍感な面もあり、副官のジュン・ソから度々無能だと叱られる。 その一例として、シンに関するジュン・ソの説明を誤解し、シンがオ・キとキョを殺したとまで思い込んでしまったことが挙げられる。彼の単純な性格を示すもう一つの例は、自分の名前を叫んだ時である。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b192029-AQrBJNfaFOOP.png', NULL, NULL, '大塚明夫', NULL, 192029, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019096', 'AN1824', '昌文君', '張文は、後に秦の左相にまで昇進した官吏であり、王である嬴政に対して極めて忠実である。かつては名高い武将であり、槍の腕前も優れていた。かつては、斉王やヒョと共に戦場で戦ったこともある。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n65399-7Wn91xpF2u3s.jpg', NULL, NULL, '仲野裕', NULL, 65399, 'SUPPORTING', 30) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019097', 'AN1824', '太后', '王太后は、若々しい容姿を今も保っている、極めて美しい成熟した女性である。その瞳には人を魅了する眼差しがあり、独特な官能的な雰囲気を漂わせている。  若い頃、ビ・キは人生に対して無邪気で、ほとんど純真とも言えるような視線を持っていたが、趙で人質として過ごした日々における恐ろしい苦難を経験した後、彼女は冷酷で残酷な人物へと変わり、秦の王太后となってからは、虚栄心と傲慢さに満ちた人物となり、もはや', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b188824-mvh65tdU0CeU.jpg', NULL, NULL, '坪井木の実', NULL, 188824, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019098', 'AN1824', '騰', '騰は王奇の側近であり、自身も軍人であるようだ。王奇の計画について、実際に把握しているのは彼だけである。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/66931-NgtPIjU6TQnI.jpg', NULL, NULL, '亮夫加藤', NULL, 66931, 'SUPPORTING', 188) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019099', 'AN1824', '紫伯', '石白は魏国の大将軍である。彼は「魏の七火竜」の一員であり、その実力は「趙の三大天」や「秦の六大将軍」に匹敵する大将軍たちである。 しかし、内部抗争が発生し、石白を含む3人の将軍が他の将軍3人を殺害した一方、五啓は中立を保った。その罰として、石白と他の2人の将軍は14年間、地下の牢獄に幽閉された。石白は魏随一の槍の達人と言われている。彼の武', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b197691-20JkpRfOy17W.jpg', NULL, NULL, '田村真', NULL, 197691, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019100', 'AN1824', '靈鳳', 'レイ・オは魏の「七火竜」の一員であり、その能力は趙の「三大大天」や秦の「六大将軍」に匹敵するものであった。  ある時、レイオはガイ・モと共に、タイ・ロ・ジ、ベン・ト、ショウ・センという他の三人の火竜たちとの対立において、シー伯爵の側に立った。タイ・ロ・ジは、シー伯爵の妹の死の直接の責任者であった。その結果、敵対する火竜たちは全員死亡した。  その罰として、レイオと他の二人の将軍は', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b192027-5KX0pCSflwWz.png', NULL, NULL, '田丸篤志', NULL, 192027, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019101', 'AN1824', '蒙驁', '身分：　婚姻状況：　未亡人　髪色：白　親族：　莫布（息子）　莫アキ （娘） 莫天 （孫） 莫基 （孫） 国：斉（出身）、秦　秦の莫戈軍を率いた名将「白羅」は、名将・莫布の父であり、莫天と莫基の祖父であった。  容姿：体格ががっしりとした老人で、長い髭を生やしていた。    性格：   ステータス 筋力  85（レン・パを押し返すほどの強さ） 指導力  90 In', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b185031-xNR5a0qTMk30.jpg', NULL, NULL, '伊藤和晃', NULL, 185031, 'SUPPORTING', 26) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019102', 'AN1824', '嫪毐', '羅愛は、良飛によって宦官として王室の後宮に連れてこられたが、彼の本当の役割は……その後、彼は愛国の王となった。彼の陰茎は、荷車の車輪さえも支えられるほど硬くなると伝えられている。', 40, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b280430-tkKZATsBWYai.jpg', NULL, NULL, '坂詰貴之', NULL, 280430, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
