INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019145', 'AN1826', '桜坂しずく', 'Shizuku Osaka is one of thirteen members of the Nijigasaki High School Idol Club. She was a member of the original group and is a member of A・ZU・NA, a subunit under Nijigaku. She is a first year and her image color is light blue.  Shizuku is a polite, level-headed and diligent First Year student at Nijigasaki High with a passion for theatre and stage acting. She is a prolific member of the school''s theatre club and it often shows in conversations where her enthusiasm for the subject surfaces.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b132798-tQmPY2jH5vki.png', '4月3日', 'A', '前田佳織里', 157, 132798, 'MAIN', 382) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019146', 'AN1826', '優木せつ菜', 'Setsuna Yuki is one of thirteen members of the Nijigasaki High School Idol Club. She was the leader and founder of the original group and is a member of A・ZU・NA, a subunit under Nijigaku. She is a second year student and her color is scarlet red. The name "Setsuna Yuki" came from the characters of a light novel that she read.  Setsuna is passionate and headstrong, but kind and mature. She has a habit of taking on too much work and not wanting to burden friends with her problems. Setsuna has an u', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b132796-awCtbFB69vjx.png', '8月8日', 'O', '楠木ともり', 154, 132796, 'MAIN', 844) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019147', 'AN1826', '天王寺璃奈', '天王寺璃奈は、虹ヶ崎高校アイドル部の13人のメンバーの一人である。彼女は「虹学」傘下のユニット「QU4RTZ」のメンバーでもある。高校1年生で、イメージカラーは「ペーパーホワイト」だが、しばしば灰色で表現される。   リナは、表情で感情を表すことができないと自認する内気な少女だ。彼女は「リナちゃんボード」と呼ばれる紙やメモ帳、あるいは電子ディスプレイで顔を隠し、そこに自分の感情を表示している。彼女はエネルギッシュで自信に満ちており、パフォーマンスでは', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b132800-80RT7p4ZbtBC.png', '11月13日', 'B', '田中ちえ美', 149, 132800, 'MAIN', 851) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019148', 'AN1826', '宮下愛', '好きな食べ物：ぬか漬け　宮下愛は、虹ヶ崎高校アイドル部の13人のメンバーの一人です。彼女は、虹学傘下のユニット「ダイバーディーバ」のメンバーでもあります。イメージカラーはウルトラオレンジです。   愛は「ギャル」風のファッションセンスを持ち、その一方で心優しく、誰の悩みにも寄り添って助けようとする意志の持ち主だ。そのため、学校でもアイドルとしても絶大な人気を誇っている。彼女は、同じクラブのメンバーである天王寺璃奈とよく一緒にいる姿が見られ、愛は璃奈が内気な性格と向き合い、それを克服できるようサポートしている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b132799-mWXBIgFlmAtU.png', '5月30日', 'A', '村上奈津実', 163, 132799, 'MAIN', 410) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019149', 'AN1826', 'エマ・ヴェルデ', 'エマ・ヴェルデは、虹ヶ崎高校アイドル部の13人のメンバーの一人です。彼女はオリジナルメンバーの一人であり、虹学傘下のユニット「QU4RTZ」のメンバーでもあります。高校3年生で、イメージカラーは薄緑です。   エマはスイス出身で、8人の弟妹がいる。以前はY.G.インターナショナル・アカデミーに通っていた。エマは時折、簡単なイタリア語を話すことがあり、スイスの中でもイタリア語圏の出身であることを示唆している。また、日本の文化に馴染むのに苦労することもあるが、', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b132802-5DyQpfwKMxuq.png', '2月5日', 'O', '指出毬亜', 166, 132802, 'MAIN', 212) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019150', 'AN1826', '三船栞子', '三船栞子は、虹ヶ崎高校アイドル部の13人のメンバーの一人である。彼女は「虹学」傘下のユニット「R3BIRTH」のメンバーでもある。1年生で、イメージカラーは翡翠色である。  栞子は、穏やかで学業優秀な性格だと言われている。日本の伝統を重んじ、伝統舞踊や生け花を習ってきた。人の長所や短所を見抜く才能があり、その才能を活かして、虹ヶ崎高校の生徒たちが部活動で成功できるようサポートしている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b208996-ru4EFXjTNQVN.png', '10月5日', 'AB', '小泉萌香', 160, 208996, 'MAIN', 261) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019151', 'AN1826', '高咲侑', '高咲侑は、『ラブライブ！虹ヶ崎高校アイドル部』のメイン主人公であり、虹ヶ崎高校アイドル部の13人のメンバーの一人です。彼女は「ニジガク」のマネージャー、作詞家、そして創設者です。高校2年生で、イメージカラーは黒です。   ユウは、虹ヶ崎高校でスクールアイドルに夢中になり始めた新進気鋭のファンであり、トレードマークの太ももまでのハイソックスと、先端を緑色に染めたツインテールを身につけている姿がよく見られる。彼女は上原歩夢と幼なじみで、二人は切っても切れない仲であり、共に育ってきた。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b170349-1hYaNLYsApgn.png', NULL, NULL, '矢野妃菜喜', 156, 170349, 'MAIN', 329) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019152', 'AN1826', 'ミア・テイラー', 'ミア・テイラーは、虹ヶ崎高校アイドル部の13人のメンバーの一人です。彼女は「虹学」傘下のユニット「R3BIRTH」のメンバーでもあります。高校3年生で、イメージカラーはプラチナシルバーです。最近ニューヨークから転校してきたばかりで、英語と日本語の両方を流暢に話します。   名門の音楽一家に生まれたにもかかわらず、ミアは家でゴロゴロしてハンバーガーばかり食べる生活の方がずっと好きだ。ランジュからは「音楽の神童」と見なされており、以前はアメリカの大学生だったが、', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b250499-kWKatw034nQh.png', '12月6日', 'AB', '内田秀', 156, 250499, 'MAIN', 194) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019153', 'AN1826', '中須かすみ', '中須かすみは、虹ヶ崎高校アイドル部の13人のメンバーの一人です。彼女はオリジナルメンバーの一人であり、虹学傘下のユニット「QU4RTZ」のメンバーでもあります。高校1年生で、イメージカラーはパステルイエローです。  かすみは「かわいいもの」なら何でも大好きで、アイドルに対する並外れた愛情は強く、情熱的だ。業界を席巻しナンバーワンになることを目標としており、1位以外になると負けず嫌いが激しくなり、妨害行為や不正行為に及ぶことさえある。彼女はニ', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b132797-S4HiLTUyyrB7.png', '1月23日', 'B', '相良茉優', 155, 132797, 'MAIN', 532) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019154', 'AN1826', 'ショウ・ランジュ', 'ショウ・ランジュは、虹ヶ崎高校アイドル部の13人のメンバーの一人です。彼女は「虹学」傘下のユニット「R3BIRTH」のメンバーです。高校2年生で、イメージカラーはローズゴールドです。最近香港から転校してきたばかりで、北京語と広東語の両方を流暢に話します。  カリスマ性あふれる少女という一面を見せつつも、その独特な性格ゆえに、周囲を不意を突くこともある。彼女は、周囲の人々が自分と同じように優れた成果を上げられるよう、時に厳しい要求を突きつける傾向があり、それが彼女を…', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b250500-xJlndoJoa7Bx.png', '2月15日', 'B', '法元明菜', 165, 250500, 'MAIN', 332) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019155', 'AN1826', '上原歩夢', 'Ayumu Uehara is one of thirteen members of the Nijigasaki High School Idol Club. She is a member of A・ZU・NA, a unit under Nijigaku. She is a second year student and her image color is light pink.   She is hard working and believes that trying your best is the only thing to do. She is kind, sociable and wants everyone to succeed. Ayumu can also be rather clumsy at times.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b132803-d5TltKLMcMMc.png', '3月1日', 'A', '大西亜玖璃', 159, 132803, 'MAIN', 430) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019156', 'AN1826', '近江彼方', '近江彼方は、虹ヶ崎高校アイドル部の13人のメンバーの一人です。彼女は初代メンバーの一人であり、虹学傘下のユニット「QU4RTZ」のメンバーでもあります。高校3年生で、イメージカラーはバイオレットです。   カナタは常に全力を尽くしている……たとえ会話の途中で居眠りをしてしまい、そうは見えない時があっても。彼女は妹のハルカを深く思いやり、妹に関することになると底知れぬエネルギーを引き出す。理想的なパフォーマンス、f', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b132801-Eq8JToBrw9PR.png', '12月16日', 'O', '鬼頭明里', 158, 132801, 'MAIN', 452) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019157', 'AN1826', '朝香果林', '朝香果林は、虹ヶ崎高校アイドル部の13人のメンバーの一人です。彼女は「虹学」傘下のユニット「ダイバーディーヴァ」のメンバーです。高校3年生で、イメージカラーはロイヤルブルーです。   カリンはとても大人っぽく、どこか色気のある雰囲気を醸し出している。自分は他のメンバーのような「かわいい」アイドルではないと自認しており、その大人っぽい魅力を自信を持って駆使して観客を魅了している。時折、些細なことでくよくよしたり、子供っぽい一面を見せることもある。また、方向音痴で、よく道に迷ってしまう。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b132795-EMhlEfeTQGVT.png', '6月29日', 'AB', '久保田未夢', 167, 132795, 'MAIN', 371) ON CONFLICT DO NOTHING;
