INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019821', 'AN1863', 'パイ', 'Pie (パイ Pai?) comes to Earth with Tart to aid Kish in preparing the planet of the arrival of Deep Blue. Serious natured, he is calmly analytical during his initial attacks on the Mew Mews, scientifically escalating the &quot;mortality rate&quot; of each chimera anima he sends and, when they are defeated, noting that &quot;stronger tactics will be needed. Pie, like the other aliens, has the ability to fly and to transport himself. He attacks using chimera anima creations and with physical attacks', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/13399.jpg', '2月13日', NULL, '梅原裕一郎', NULL, 13399, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019822', 'AN1863', '青山雅也', NULL, 13, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b2695-MTBg0KlsTNLZ.jpg', '5月22日', NULL, '内田雄馬', NULL, 2695, 'SUPPORTING', 33) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019823', 'AN1863', '本条みわ', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b40048-Yr7DlhDpWnsH.png', NULL, NULL, '鈴木愛奈', NULL, 40048, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH019824', 'AN1863', 'マシャ', 'Masha (マシャ Masha?) is a robot created by Ryou to detect chimera animas and mew aqua. Originally called by her model number of R2000, Ichigo renames her &quot;Masha&quot; after her crush Masaya. Masha likes the new name and likes being with Ichigo. After the aliens are defeated, Masha chooses to stay with Ichigo when Ichigo goes to London with Masaya. In addition to detecting the chimera animas, Masha eats the jelly-fish like parasites that come out of the victims after the Mew Mews defeat them. ', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/13402.jpg', NULL, NULL, '石原夏織', NULL, 13402, 'SUPPORTING', 34) ON CONFLICT DO NOTHING;
